  "artistSort": "Michel-Ange",
  "civId": "occident",
  "periodId": "occ_renaissance_italienne",
  "civName": "Occident chrétien & moderne",
  "civilization": "Italie (Rome / Haute Renaissance)",
  "subpart": "Le captif musculeux se cambrant dans une torsion violente pour briser les liens qui l'emprisonnent dans la pierre",
  "date": "1513 – 1515",
  "dateDisplay": "1513-1515",
  "century": "XVIe siècle",
  "centuryDisplay": "XVIe s.",
  "centuryNumeric": 1513,
  "format": "Sculpture monumentale en marbre en ronde-bosse",
  "dimensions": "Hauteur 209 cm",
  "site": "Musée du Louvre, Paris (France)",
  "originSite": "Second projet du tombeau de Jules II, Rome",
  "domain": "sculpture_statuaire",
  "artifactType": "Statuaire mythologique & allégorique (ronde-bosse)",
