  "isHighlight": true,
  "backgroundId": "none",
  "deptBanner": "https://lh3.googleusercontent.com/pw/AP1GczPY6zIkwJb1Tddx8j2B_x9Rmr4EEfELpy00aatGZCTlszmqNSg14K3oOJQDTl3tV3-lPLpJ2HOSkhBvwjl3w3FuueunhZcqrsKwfQaPYPkDqcaS3j3OX4k3rb8QYnP3cX3ggunMFK3Gdik87HiYy5HU7g=w1836-h779-s-no-gm?authuser=0",
